+      throw new Error('INVALID_INPUT');
+    }
+    const amount = Number(digits);
+    if (!Number.isSafeInteger(amount)) throw new Error('INVALID_INPUT');
+    ids.add(id);
+    records.push({ id, amount });
+  }
+  return records;
+}
